SELECT
t1.*,
t2.balance,
t2.consume_amount,
t2.order_num,
au.author_level
FROM
member_user t1
LEFT JOIN member_user_account t2 ON t1.id = t2.user_id
LEFT JOIN author_user au on t1.id = au.user_id


        AND t1.id = #{reqVO.id}


        AND t1.nickname LIKE CONCAT('%', #{reqVO.nickname}, '%')


        AND t1.mobile = #{reqVO.mobile}


        AND t1.status = #{reqVO.status}


        AND t1.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}


        AND t1.last_login_time BETWEEN #{reqVO.lastLoginTime[0]} AND #{reqVO.lastLoginTime[1]}


        AND t1.origin = #{reqVO.origin}


        AND t1.register_ip = #{reqVO.registerIp}


        AND t1.last_login_ip = #{reqVO.lastLoginIp}



        AND t1.referrer = #{reqVO.referrer}



        AND t1.referrer_type = #{reqVO.referrerType}






                    AND t1.live_code_id IN

                        #{item}



                    AND 1 = 0




                    AND t1.referrer IN

                        #{item}



                    AND 1 = 0



                AND (
                (t1.referrer_type = 3

                    AND t1.live_code_id IN

                        #{item}



                    AND 1 = 0

                )
                OR
                (t1.referrer_type = 5

                    AND t1.referrer IN

                        #{item}



                    AND 1 = 0

                )
                )





        AND t1.live_code_id =  #{reqVO.liveCodeId}





                AND t2.consume_amount = 0


                AND t2.consume_amount > 0





        AND EXISTS (
        SELECT
        1
        FROM member_user_follow t3
        WHERE t3.user_id = t1.id
        AND t3.target_type = 1
        AND t3.status = 0
        AND t3.target_id in

            #{item}

        )



        AND t1.referrer in

            #{item}





        ORDER BY



                    t2.consume_amount


                            ASC


                            DESC




                    t2.order_num


                            ASC


                            DESC




                    t1.id DESC





        ORDER BY t1.id DESC

select qr_code_url
from wx_work_setting
where id = #{id}

select user_id
from wx_work_setting
where id = #{id}

SELECT live_code_id AS liveCodeId, COUNT(*) AS registerPeople FROM member_user WHERE live_code_id IN
#{id}
GROUP BY live_code_id

SELECT
u.id AS userId,
u.avatar_url AS avatarUrl,
u.nickname,
u.partner_id AS superiorUserId,
sup.nickname AS superiorNickname,
u.status AS status,
u.partner_time AS joinTime
FROM member_user u
LEFT JOIN member_user sup ON sup.id = u.partner_id

    AND u.identity = 1 AND u.deleted = 0

        AND u.status = #{reqVO.status}


        AND (
        u.nickname LIKE CONCAT('%', #{reqVO.userInfo}, '%')
        OR u.mobile = #{reqVO.userInfo}
        OR u.id = #{reqVO.userInfo}
        )


        AND (
        sup.nickname LIKE CONCAT('%', #{reqVO.superiorInfo}, '%')
        OR sup.mobile = #{reqVO.superiorInfo}
        OR sup.id = #{reqVO.superiorInfo}
        )


        AND u.partner_id = #{reqVO.partnerId}


ORDER BY u.id DESC

SELECT partner_id AS partnerId, COUNT(1) AS cnt FROM member_user WHERE identity = 1 and deleted= 0 AND partner_id IN
#{id}
GROUP BY partner_id

SELECT lock_fans_id AS partnerId, COUNT(1) AS cnt FROM member_user WHERE deleted = 0 AND lock_fans_type = 1 AND lock_fans_id IN
#{id}
GROUP BY lock_fans_id

SELECT ( SELECT COUNT(1) FROM member_user mu
AND mu.deleted = 0 AND mu.lock_fans_id IS NOT NULL AND mu.lock_fans_id > 0 AND mu.lock_fans_type = 1
AND mu.lock_fans_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
AND mu.lock_fans_id IN
#{id}
) AS customerCount, ( SELECT COUNT(1) FROM member_user mp
AND mp.deleted = 0 AND mp.identity = 1
AND mp.partner_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
AND mp.id IN
#{id}
) AS partnerCount

SELECT referrer_type AS referrerType, CASE referrer_type WHEN 0 THEN '散户' WHEN 1 THEN '作者' WHEN 2 THEN '合伙人' WHEN 3 THEN '渠道-推广员' WHEN 4 THEN '渠道-客服' ELSE '其他' END AS referrerTypeName, COUNT(id) AS registerCount FROM member_user WHERE deleted = 0
AND create_time BETWEEN #{createTimes[0]} AND #{createTimes[1]}
GROUP BY referrer_type

SELECT COUNT(DISTINCT u.id)
FROM member_user u
WHERE u.deleted = 0
AND u.last_login_time >= #{todayStart}
AND u.last_login_time <= #{todayEnd}
AND NOT EXISTS (
SELECT 1
FROM member_user u2
WHERE u2.id = u.id
AND u2.last_login_time > #{thirtyDaysAgoStart}
AND u2.last_login_time <= #{yesterdayEnd}
)

SELECT u.referrer AS referrer, COUNT(DISTINCT u.id) AS accessUserCount FROM member_user u WHERE u.deleted = 0 and u.referrer_type in (3, 4) AND u.referrer IN
#{referrer}
GROUP BY u.referrer
